insert into public.courses (slug, title, description, category, level, price_kobo, hours, rating, emoji, gradient, outcomes, published) values ('full-stack-web-development', 'Full-Stack Web Development', 'Go from your first line of HTML to deploying production-ready apps with React, Node.js, databases and authentication. Build a portfolio project that employers actually want to see.', 'Programming', 'Beginner', 4500000, 38, 4.8, '💻', '#0a84ff,#5e5ce6', array['Build responsive interfaces with HTML, CSS and modern JavaScript','Create full-stack apps with React, Next.js and Node APIs','Model data and write queries with PostgreSQL','Deploy, secure and maintain a live application']::text[], true) on conflict (slug) do update set title = excluded.title, description = excluded.description, category = excluded.category, level = excluded.level, price_kobo = excluded.price_kobo, hours = excluded.hours, rating = excluded.rating, emoji = excluded.emoji, gradient = excluded.gradient, outcomes = excluded.outcomes, published = excluded.published;
