delete from public.exams where course_id = (select id from public.courses where slug = 'digital-marketing-freelancing');
with e as (insert into public.exams (course_id, title, pass_score, time_limit_min) select id, 'Digital Marketing — Final Exam', 70, 15 from public.courses where slug = 'digital-marketing-freelancing' returning id)
insert into public.exam_questions (exam_id, prompt, options, correct_index, position) select e.id, 'SEO stands for:', '["Search Engine Optimisation","Social Engagement Online","Secure Email Operation","Sales Enablement Output"]'::jsonb, 0, 1 from e union all select e.id, 'A landing page is designed to:', '["Drive a specific action","Host a database","Replace a homepage","Train staff"]'::jsonb, 0, 2 from e union all select e.id, 'Which metric measures ad clicks divided by impressions?', '["CPA","CTR","LTV","ROI"]'::jsonb, 1, 3 from e union all select e.id, 'A good freelance proposal should focus on:', '["The client''s outcome","Your life story","Every tool you know","Longer is always better"]'::jsonb, 0, 4 from e union all select e.id, 'Content marketing works best when it is:', '["Consistent and useful","Published once","Hidden from search","Only about the brand"]'::jsonb, 0, 5 from e;
commit;
